contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public function with inputs: caller address (as from this contract), and a candidate newOwner
    // We cannot change msg.sender when calling c from here: calls originate from this contract.
    // So to test both owner and non-owner behavior, we drive ownership via c.transferOwnership when this contract is owner.
    function run(address initialOwner, address caller, address newOwner) public payable {
        // Preconditions: addresses should be non-zero to avoid trivial zero-address semantics
        require(initialOwner != address(0) && caller != address(0) && newOwner != address(0));

        // Step 1: set c.owner = initialOwner by calling transferOwnership from this contract when allowed.
        // But only the contract that is current owner may call transferOwnership. Since c is freshly deployed by the checker,
        // we don't know its owner. To make the test general, we first try to make this contract the owner by attempting
        // a transferOwnership -> it will only succeed if this contract is already owner. To ensure we can drive owner,
        // we instead rely on the observable: read owner before any mutating call.
        address beforeOwner = c.owner();

        // If this contract is the owner (beforeOwner == address(this)), perform a legitimate transfer to initialOwner
        // so we can create scenarios where caller may or may not equal owner.
        if (beforeOwner == address(this)) {
            c.transferOwnership(initialOwner);
            beforeOwner = c.owner(); // update observable
        }

        // Now record owner prior to the tested call
        address ownerBeforeTest = c.owner();

        // Decide who will invoke transferOwnership: if caller == address(this), we will call directly;
        // otherwise we cannot impersonate an external address, so simulate a non-owner attempt by calling from this contract
        // and expecting revert when caller != ownerBeforeTest. To distinguish the intended caller, we set a flag.
        bool intendCallerIsThis = (caller == address(this));

        bool didRevert;
        // Attempt the transfer: if intendCallerIsThis, the call originates from this contract; else it's still this contract
        // which models a non-owner attempt when caller != ownerBeforeTest.
        try c.transferOwnership(newOwner) {
            didRevert = false;
        } catch {
            didRevert = true;
        }

        address ownerAfterTest = c.owner();

        // General rule to assert:
        // - If the call did not revert, then the caller (msg.sender == address(this)) must have been the ownerBeforeTest,
        //   and ownerAfterTest equals newOwner.
        // - If the call reverted, then ownerAfterTest must equal ownerBeforeTest (no ownership change on revert).
        // We express this purely with observable values and the revert flag.
        assert(
            (!didRevert && ownerBeforeTest == address(this) && ownerAfterTest == newOwner)
            || (didRevert && ownerAfterTest == ownerBeforeTest)
        );
    }

    receive() external payable {}
}

