        require(true);

        // Read initial owner
        address initialOwner = c.owner();

        // If callAsOwner is true, attempt to make this contract the owner by invoking transferOwnership
        // from the current owner. Since msg.sender for calls to c is this contract, to simulate the original
        // owner doing the call we must rely on the freshly deployed c: the deployer of c is external and not
        // this contract, so we cannot assume we can become owner unless we are already owner. Therefore,
        // we only attempt a transferOwnership here if this contract is already the owner to keep this top-level.
        // Check whether this contract is owner now.
        bool thisIsOwner = (initialOwner == address(this));

        // Record owner before any tested actions
        address before = c.owner();

        // 1) Call owned() (may revert if not owner); capture whether it reverted and owner after.
        bool ownedReverted;
        try c.owned() {
            ownedReverted = false;
        } catch {
            ownedReverted = true;
        }
        address afterOwned = c.owner();

        // 2) Attempt transferOwnership to newOwner and record whether it reverted and resulting owner.
        bool transferReverted;
        try c.transferOwnership(newOwner) {
            transferReverted = false;
        } catch {
            transferReverted = true;
        }
        address afterTransfer = c.owner();

        // General rule to assert:
        // - owned() never changes owner: afterOwned == before
        // - If this contract was the owner before calling transferOwnership, the call must succeed and owner becomes newOwner.
        // - If this contract was not the owner before calling transferOwnership, the call must revert and owner remains unchanged.
        assert(
            afterOwned == before
            && (
                (thisIsOwner && !transferReverted && afterTransfer == newOwner)
                || (!thisIsOwner && transferReverted && afterTransfer == before)
            )
        );
    }

