    function run(address candidate, bool callerIsOwner) public payable {
        require(candidate != address(0));

        // read initial owner
        address ownerBefore = c.owner();

        // If we want this contract to be the owner for the test, and it's not already, try to make it owner.
        // Note: the only way to change owner is via transferOwnership called by current owner. At deployment
        // owner might be address(0) or msg.sender of deploy; but we may try to transfer only if ownerBefore == address(this)
