        if (callerIsOwner && ownerBefore == address(this)) {
            // as owner, call transferOwnership to candidate to test successful owner call
            c.transferOwnership(candidate);
            // after successful transfer, owner should be candidate
            address ownerAfter = c.owner();
            assert(ownerAfter == candidate);
            return;
        }

        // Otherwise, attempt transfer as non-owner and catch whether it reverts.
        bool reverted;
        try c.transferOwnership(candidate) {
            reverted = false;
        } catch {
            reverted = true;
        }

        address ownerAfterAttempt = c.owner();

        // General rule: if non-owner call reverted, owner unchanged; if non-owner call did not revert, owner must have changed to candidate.
        // This covers both possibilities and enforces that only owner can change ownership.
        assert(reverted ? (ownerAfterAttempt == ownerBefore) : (ownerAfterAttempt == candidate));
    }

    receive() external payable { }
}

